     "text": "平凡不是什么值得向往的事情，应该远离它。而一个人是否平凡不应由外人评价，只要实现了自己的内心价值，我们都可以将其称之为不平凡的人，哪怕这个价值在你我眼中是很微不足道轻而易举的事情。",
