    "锻炼的所有好处几乎都产生于最后阶段。我想增强力量，就必须等到肌肉纤维断裂，神经纤维感到疼痛才行，因为这时候自然机制才会予以过度补偿，纤维在48小时后会变得更加坚韧。"
