    "在数字经济时代，如何使数字资产等价值能在互不信任的主体之间、在不可信的网络上可信传递？",
    "区块链并不是新的技术，而是由加密算法、P2P通信等“老”的技术组合而来的，而这个组合看似简单，却实实在在地解决了传统互联网中无法传输价值与信任的问题",
    "信息传递可以重复流通，但价值传递却要保持唯一性。",
    "而区块链是一个价值交换（Value-Exchange）协议。",
    "市场上出现了各种各样的基于比特币底层的区块链技术加密的数字货币，例如，域名币、彩色币、元币、狗狗币、莱特币等。",
    "区块链第一次创造性地将密码学、分布式、博弈论、P2P协议等技术有机地组合在一起，使其具备去中心化、账务公开、不可篡改、可追溯等特点。区块链最大的创新是第一次用技术解决了人类的共识问题，用理性的技术为人类建立信任提供了方法。",
    "传统数据库可以增、删、改、查（CURD），而区块链只能增加和查询，不能修改、不能删除。",
