    "被判了无期徒刑的犯人确实也有表示悔过的，也可以说大多数都表示悔过。但是，这些犯人的态度，跟很多被判处死刑的犯人在某种热情的驱使下所表现出来的悔恨有很大不同。真正达到了宗教式心醉神迷的真诚悔过程度的，只有在死刑犯中才能看到。",
