   "quotes": [],
   "highlights": [
    "Cloud表示应用程序位于云中，而不是传统的数据中心；Native表示应用程序从设计之初就考虑到云的环境，为云而生，生于云而长于云，充分利用和发挥云平台的弹性和分布式优势。",
    "起初Docker是由单一二进制完成的，Docker Client和Docker Daemon是同一个二进制，基于LXC实现容器的namespace隔离和cgroup限制",
    "宿主机可以看到容器中的进程，但是容器中的进程看不到宿主机上的其他进程。这就是PID namespace的作用。在容器中启动进程，其实就是在容器这个父进程下启动一个子进程。容器为进程提供了一个隔离的环境，容器内的进程无法访问容器外的进程。",
    "containerd创建的普通容器默认capabilities有如下权限，而如果该容器是特权容器，则支持所有capabilities。",
    "可以通过/proc/<pid>/cgroup查看进程所在的Cgroup namespace内的cgroup信息。",
    "高级容器运行时：主要负责镜像的管理，转换为低级容器运行时能识别的环境，为容器的运行做准备，向上对接容器编排层",
    "containerd是通过systemd来管理的，安装包中包含对应的containerd.service文件：/etc/systemd/system/containerd.service。",
    "cri-o和containerd并列作为Kubernetes官方推荐的两个容器运行时之一",
    "之后会为Sandbox创建并启动一个特殊的容器，即Pause容器，然后将该容器加入上述的网络命名空间中",
    "manifests中内容是一个JSON结构的结构体，其中，无论是config还是layer，都有3个属性。"
   ],
