    "一位大爷在拍摄长城。长城由近及远，蜿蜒曲折。这就是常说的“有画面深度”“有纵深”等。",
    "要么用两枚硬币挡住两只眼睛——离眼睛很近；要么就把电视能搬多远搬多远，直到可以被您手中的硬币挡住。",
    "拍摄距离越近，透视效果越明显；拍摄距离越远，透视效果就越不明显，直到可能看不出来。",
    "测光是测光，曝光是曝光，测光和曝光模式（光圈优先、快门优先、手动曝光）没有直接关系，测光和对焦模式、对焦点选择模式更没有直接关系。测光就是相机衡量测光区域亮度的功能。",
    "这个曝光参数说的其实就是光圈、快门速度、感光度。",
    "如果有离您相机很近的前景，比如铁丝网、栅栏等躲不开的东西，则这些东西可能会消失。因为大光圈强大的虚化能力，能将很近的东西虚化成看不到。",
    "光圈优先、快门优先以及手动曝光是我们要学习的，通常也是必须学会以及学会就足够的。",
    "对于拍摄多张照片进行拼接，或者后期堆栈（叠加）合成照片，我们也要使用M挡，保证用同一个参数拍摄，这样才能成功合成照片。",
    "最后将以上内容给大家总结成一句话：蓝色是冷色，但是色温高；红色是暖色，但是色温低。"
