    "柳比歇夫则不然，他不仅身体力行过着合乎道德的生活，而且似乎对道德有着某种自我设定的精确标准，而这同样与其生活方法密切相关。",
    "从1916年开始记日记以来，据我所知，柳比歇夫从无一日中断，无论是在革命期间还是在战争年代，无论是躺在病床上还是坐在外出科考的火车上，总之，竟然没有任何原因、任何事件、任何情况能够阻碍他在日记里写上几行。",
    "任何一个哪怕最最天才的发现，倘若把它诞生之前的推理一一罗列出来，那其中的种种愚蠢而荒谬的可笑揣测一定会多到令人吃惊。",
