    "时间统计法不承认有不能利用的时间。一切时间都同样宝贵。对一个人而言，不应该有坏的时间、空的时间、多余的时间，也不应当有休息时间。所谓休息，就是不同工作的交替，就像合理的耕地轮作一样。",
