    "这种想法是优绩至上思维的起源，反映了这样一种信念，即道德世界的法则是“美德带来成功，恶行必致苦难”。这与人们熟悉的当代观点相差不远，即财富标示着天分和勤劳，而贫穷意味着懒惰。"
