    "内隐的一个假定是，绝大多数人都有能力工作，可以通过出售工作能力获取相应收益，用以维持生活。",
    "工厂体系的诞生事实上瓦解了工匠和他们的事业之间的亲密关系，这种关系被“工作伦理”视为理所当然的",
    "上层阶级希望劳动者只具有奴隶的价值。工人应该是勤勉的、专注的，永远不要考虑自己，只对主人忠诚，依附于主人",
