    "除去现代另一项伟大发明——大规模征兵，工厂是现代社会最主要的“圆形监狱”。",
    "越来越多的人认为，从工匠变成工人时失去的人的尊严，只有通过赢得更多盈余才能恢复。这种变迁中，努力工作能使人们道德升华的呼声日益衰弱。现在，衡量人们声望和社会地位的是工资的差别，而不是勤于工作的道德或惰于工作的罪恶。",
    "在现代性的工业阶段，一个事实不容置疑，那就是每个人在拥有其他身份之前，首先必须是一个生产者。在现代性的第二阶段，即消费者的时代，这个不容置疑的事实变成了：人首先要成为消费者，才能再拥有其他特别的身份。"
