    "这个问题产生于我们的思维结构：我们不学习规律，而是学习事实，而且只学习事实。我们似乎不太善于认识到我们的超规律（我们倾向于不学习规律的规律）。我们蔑视抽象的东西——疯狂地蔑视。"
